import{_ as i,r as s,o as n,c as l,e as t,d,a,b as o}from"./chunks/framework.Cq4gzU1W.js";const v=JSON.parse('{"title":"Wordpress, git y wikis","description":"Despliegue de aplicaciones","frontmatter":{"title":"Wordpress, git y wikis","description":"Despliegue de aplicaciones","weight":25},"headers":[],"relativePath":"01_Presentacion/02_Modulos/servicios/oscar/index.md","filePath":"01_Presentacion/02_Modulos/servicios/oscar/index.md"}'),c={name:"01_Presentacion/02_Modulos/servicios/oscar/index.md"};function p(m,e,u,g,h,f){const r=s("Markmap");return n(),l("div",null,[e[0]||(e[0]=t('<figure class="imgproc"><figcaption>Teresa Martínez</figcaption></figure><p><span class="hugo-color text-alert">Teresa Martínez,</span><span class="hugo-color text-warning">Ingeniera en informática</span></p><p>Profesora del centro.</p><h4 id="modulo-3-manejo-de-aplicaciones-web-funcionales-wordpress" tabindex="-1">Módulo 3: Manejo de aplicaciones web funcionales: Wordpress <a class="header-anchor" href="#modulo-3-manejo-de-aplicaciones-web-funcionales-wordpress" aria-label="Permalink to &quot;Módulo 3: Manejo de aplicaciones web funcionales: Wordpress&quot;">​</a></h4><div class="hugo-pageinfo"><figure class="imgproc"></figure><hr class="hugo-line"><p>El conocimiento del manejo de herramientas ya plenamente operativas será de gran ayuda a la hora de integrar los conocimientos aprendidos en el curso.</p><p>Para ello, nada mejor que elegir uno de los Gestores de contenidos (CMS) más extendidos y conocidos del mundo: Wordpress.</p><p>Esta herramienta nos permite una enorme adaptación de características a nuestras necesidades.</p></div><h4 id="modulo-3-control-de-versiones-git" tabindex="-1">Módulo 3: Control de Versiones: Git <a class="header-anchor" href="#modulo-3-control-de-versiones-git" aria-label="Permalink to &quot;Módulo 3: Control de Versiones: Git&quot;">​</a></h4><div class="hugo-pageinfo"><p><img src="https://upload.wikimedia.org/wikipedia/commons/thumb/e/e0/Git-logo.svg/320px-Git-logo.svg.png" alt="Control de versiones: Git" title="Control de versiones: Git"></p><hr class="hugo-line"><ul><li><p>El desarrollo de software moderno sería inconcebible sin la integración del trabajo en equipo.</p></li><li><p>Para ello, resulta imprescindible el uso de algún sistema de control de versiones de software.</p></li><li><p>Esta herramienta nos permitirá mantener el software operativo, a la vez que continúamos sumando nuevas funcionalidades y modificamos las ya existentes.</p></li><li><p>De entre todas las herramientas disponibles se ha elegido GIT. Un moderno sistema de control de versiones usado actualmente en una gran cantidad de proyectos reales, como el kernel de Linux.</p></li></ul></div><h3 id="temario-general" tabindex="-1">Temario general <a class="header-anchor" href="#temario-general" aria-label="Permalink to &quot;Temario general&quot;">​</a></h3>',8)),d(r,{code:"IyBDb250ZW5pZG9zCiMjIHdvcmRwcmVzcwojIyBnaXQ="}),e[1]||(e[1]=a("h3",{id:"horario",tabindex:"-1"},[o("Horario "),a("a",{class:"header-anchor",href:"#horario","aria-label":'Permalink to "Horario"'},"​")],-1)),e[2]||(e[2]=a("blockquote",null,[a("p",null,"En breve el horario concreto")],-1)),e[3]||(e[3]=a("h3",{id:"examen",tabindex:"-1"},[o("Examen "),a("a",{class:"header-anchor",href:"#examen","aria-label":'Permalink to "Examen"'},"​")],-1)),e[4]||(e[4]=a("blockquote",null,[a("p",null,"En breve estableceremos la fecha del examen")],-1))])}const x=i(c,[["render",p]]);export{v as __pageData,x as default};
